const rows = $input.all();

const requiredColumns = [
  'date',
  'product_code',
  'customer_code',
  'sold_quantity'
];

const validatedRows = [];
const errors = [];

const seen = new Set();

for (let i = 0; i < rows.length; i++) {
  const row = rows[i].json;
  const rowNumber = i + 2;
  const rowErrors = [];

  // Required columns
  for (const column of requiredColumns) {
    if (!(column in row)) {
      rowErrors.push(`Missing column: ${column}`);
    }
  }

  if (rowErrors.length === 0) {

    // Date
    const date = String(row.date ?? '').trim();

    if (!date) {
      rowErrors.push('Date is missing');
    } else if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      rowErrors.push('Invalid date format. Expected YYYY-MM-DD');
    } else {
      const parsedDate = new Date(`${date}T00:00:00Z`);

      if (Number.isNaN(parsedDate.getTime())) {
        rowErrors.push('Invalid date');
      }
    }

    // Product code
    const productCode = String(row.product_code ?? '').trim();

    if (!productCode) {
      rowErrors.push('Product code is missing');
    } else if (productCode.length > 45) {
      rowErrors.push('Product code exceeds 45 characters');
    }

    // Customer code
    const customerCode = String(row.customer_code ?? '').trim();

    if (!customerCode) {
      rowErrors.push('Customer code is missing');
    } else if (!/^\d+$/.test(customerCode)) {
      rowErrors.push('Customer code must be an integer');
    }

    // Sold quantity
    const quantity = String(row.sold_quantity ?? '').trim();

    if (!quantity) {
      rowErrors.push('Sold quantity is missing');
    } else if (!/^-?\d+$/.test(quantity)) {
      rowErrors.push('Sold quantity must be an integer');
    } else if (Number(quantity) < 0) {
      rowErrors.push('Sold quantity cannot be negative');
    }

    // Duplicate check
    const duplicateKey =
      `${date}|${productCode}|${customerCode}`;

    if (seen.has(duplicateKey)) {
      rowErrors.push(
        'Duplicate record: date + product_code + customer_code'
      );
    } else {
      seen.add(duplicateKey);
    }
  }

  const validatedRow = {
    ...row,
    _row_number: rowNumber,
    _validation_errors: rowErrors,
    _is_valid: rowErrors.length === 0
  };

  validatedRows.push(validatedRow);

  if (rowErrors.length > 0) {
    errors.push({
      row: rowNumber,
      data: row,
      errors: rowErrors
    });
  }
}

return validatedRows.map(row => ({
  json: row
}));

