SELECT
  {{ JSON.stringify($json.date) }} AS date,
  {{ JSON.stringify($json.product_code) }} AS product_code,
  {{ Number($json.customer_code) }} AS customer_code,
  {{ Number($json.sold_quantity) }} AS sold_quantity,
  {{ Number($json._row_number) }} AS _row_number,

  EXISTS (
    SELECT 1
    FROM dim_product
    WHERE product_code = {{ JSON.stringify($json.product_code) }}
  ) AS product_exists,

  EXISTS (
    SELECT 1
    FROM dim_customer
    WHERE customer_code = {{ Number($json.customer_code) }}
  ) AS customer_exists,

  EXISTS (
    SELECT 1
    FROM dim_date
    WHERE date = {{ JSON.stringify($json.date) }}
  ) AS date_exists;

