const items = $input.all();

// Get the original validation results from Node 3
const node3Items = $('Validate data').all();

// Create a lookup using row number
const node3Map = new Map();

for (const item of node3Items) {
  const row = item.json;

  node3Map.set(
    Number(row._row_number),
    row
  );
}

return items.map(item => {
  const row = item.json;

  // Get original validation errors from Node 3
  const originalRow = node3Map.get(
    Number(row._row_number)
  );

  const errors = Array.isArray(originalRow?._validation_errors)
    ? [...originalRow._validation_errors]
    : [];

  // Database reference validation from Node 4
  if (Number(row.product_exists) !== 1) {
    errors.push(
      'Product code not found in dim_product'
    );
  }

  if (Number(row.customer_exists) !== 1) {
    errors.push(
      'Customer code not found in dim_customer'
    );
  }

  if (Number(row.date_exists) !== 1) {
    errors.push(
      'Date not found in dim_date'
    );
  }

  return {
    json: {
      ...row,
      _validation_errors: errors,
      _is_valid: errors.length === 0
    }
  };
});

const rows = $input.all().map(item => item.json);

const invalidRecords = rows
  .filter(row => row._is_valid !== true)
  .map(row => ({
    _row_number: row._row_number,
    date: row.date,
    product_code: row.product_code,
    customer_code: row.customer_code,
    sold_quantity: row.sold_quantity,
    _validation_errors: row._validation_errors
  }));

const validRows = rows.filter(row => row._is_valid === true);

return [{
  json: {
    validation_status: invalidRecords.length === 0 ? "VALID" : "INVALID",
    total_rows: rows.length,
    valid_rows: validRows.length,
    invalid_rows: invalidRecords.length,
    invalid_records: invalidRecords,
    validated_rows: rows
  }
}];

